        c.withdraw(); if (__ESBMC_reverted()) return;

        bool reverted = false;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
        }

        uint256 balanceAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 contractEthBefore = address(c).balance + balanceBefore;

        assert(
